def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    urgent_opp_count = 0
    rich_opp_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_opp_count += 1
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 3:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return float(min(budget, 20.0))

    slots = supply / WATER_REQ
    tight_supply = slots < 2.0
    very_tight_supply = slots < 1.5

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2
    if very_tight_supply:
        danger += 2
    elif tight_supply:
        danger += 1
    if urgent_opp_count >= 2:
        danger += 1

    if danger >= 6:
        target = max(95.0, highest_prev + 3.0)
    elif danger >= 4:
        target = max(72.0, avg_prev + 2.0, highest_prev * 0.92)
    elif danger >= 2:
        target = max(48.0, avg_prev * 0.72)
    else:
        target = 24.0 if not tight_supply else 38.0

    if highest_prev >= 110:
        if danger <= 2:
            target = min(target, 34.0)
        else:
            target = max(target, 88.0)
    elif highest_prev >= 95:
        if danger <= 1:
            target = min(target, 30.0)
        else:
            target = max(target, 76.0)
    elif highest_prev >= 75:
        if danger >= 4:
            target = max(target, highest_prev + 1.5)
        else:
            target = max(target, 44.0)

    if rich_opp_count == 0 and danger <= 3:
        target *= 0.9

    if day >= 8 and hp > 5 and no_water_days == 0 and budget < 220:
        target *= 0.85

    if budget < 60:
        target = min(target, budget)
    elif budget < 120:
        target = min(target, budget * 0.85)
    else:
        target = min(target, budget * 0.7)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, min(budget, 98.0))

    if target < 0:
        target = 0.0
    if target > budget:
        target = budget

    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace for immediate pressure estimate
    yesterday_bids = []
    yesterday_pressures = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

        # If yesterday opp had low hp or died soon, treat as higher urgency
        prev_hp_after = prev.get('hp_after', None)
        if prev_hp_after is not None:
            try:
                prev_hp_after = float(prev_hp_after)
                yesterday_pressures.append(prev_hp_after)
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many full water-req units supply can cover
    # (indexing safety with int() though not strictly needed here)
    capacity_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Base aggressiveness: if supply is tight (15-18), bid more to ensure allocation.
    if supply <= (MIN_SUPPLY + 3):
        tight_factor = 1.0
    elif supply <= 20:
        tight_factor = 0.85
    else:
        tight_factor = 0.7

    # Urgency from our hp/no_water_days
    if hp <= 2 or no_water_days >= 3:
        urgency = 1.0
    elif hp <= 4 or no_water_days == 2:
        urgency = 0.85
    else:
        urgency = 0.65

    # If opponents were bidding very high yesterday, we slightly outbid the likely clearing zone.
    # Use a soft threshold around 0.85*DAILY_SALARY.
    threshold = 0.85 * DAILY_SALARY

    if highest_prev_bid >= threshold:
        # Keep some budget for later days; bid around high zone but not maxing.
        target = (highest_prev_bid * 0.92 + 3.0) * tight_factor
    else:
        # Otherwise follow average with a small premium.
        premium = max(6.0, 0.12 * avg_prev_bid)
        target = (avg_prev_bid + premium) * tight_factor

    # If we have lots of capacity units, we can bid less.
    if capacity_units >= 2:
        target *= 0.9

    # Clamp by urgency and budget
    target *= (0.85 + 0.3 * urgency)

    # Final bid constraints: never exceed budget; also avoid overshooting extreme values.
    max_reasonable = DAILY_SALARY * 1.25
    bid = min(budget, max_reasonable, target)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    # If budget is tiny, bid what we can.
    if budget <= 10:
        return budget

    return float(bid)

